import{az as s,P as l,Q as e,aQ as o}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const y=JSON.parse('{"title":"JWT","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/服务端/jwt.md","filePath":"面试题/服务端/jwt.md","lastUpdated":1782478366000}'),n={name:"面试题/服务端/jwt.md"};function t(p,a,r,i,d,c){return l(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="jwt" tabindex="-1">JWT <a class="header-anchor" href="#jwt" aria-label="Permalink to “JWT”">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to “定义”">​</a></h2><p>JSON Web Token，JSON 格式的 Web 令牌标准。</p><p>由三段 <code>.</code> 分割：<code>Header.Payload.Signature</code>，基于 <code>Base64</code> + 签名加密。</p><p>它本身不是一套完整的鉴权方案，双 Token、单点登录等都是基于它的上层设计。</p><h2 id="解析" tabindex="-1">解析 <a class="header-anchor" href="#解析" aria-label="Permalink to “解析”">​</a></h2><h3 id="_1-header" tabindex="-1">1. Header <a class="header-anchor" href="#_1-header" aria-label="Permalink to “1. Header”">​</a></h3><p>JSON 结构，描述令牌元数据，经 Base64URL 编码后成为第一段。 固定两个核心字段：</p><ul><li>alg：签名算法，最常见为 HS256（HMAC-SHA256）、RS256（RSA-SHA256）</li><li>typ：令牌类型，固定为 JWT</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">alg</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">HS256</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">typ</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">JWT</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h3 id="_2-payload-载荷" tabindex="-1">2. Payload（载荷） <a class="header-anchor" href="#_2-payload-载荷" aria-label="Permalink to “2. Payload（载荷）”">​</a></h3><p>JSON 结构，存放实际业务数据，经 Base64URL 编码后成为第二段。 <strong>关键提醒</strong>：Base64 是编码而非加密，任何人拿到 Token 都能反向解码看到内容，<strong>严禁存放密码、密钥、身份证号等敏感信息</strong>。</p><p>Payload 包含三类声明（Claim）：</p><ul><li><p><strong>注册声明（标准推荐）</strong>：预定义的通用字段，非强制但行业普遍遵循</p><ul><li><p><code>iss</code> (issuer)：签发者</p></li><li><p><code>sub</code> (subject)：主题，通常存放用户唯一 ID</p></li><li><p><code>aud</code> (audience)：受众，指定接收方</p></li><li><p><code>exp</code> (expiration time)：过期时间戳（秒级 Unix 时间）</p></li><li><p><code>nbf</code> (not before)：生效时间，在此之前不可用</p></li><li><p><code>iat</code> (issued at)：签发时间</p></li><li><p><code>jti</code> (JWT ID)：令牌唯一编号，用于防重放、做黑名单主键</p></li></ul></li><li><p><strong>公共声明</strong>：业务自定义字段，如 <code>userId</code>、<code>role</code>、<code>username</code></p></li><li><p><strong>私有声明</strong>：通信双方约定的非公开字段</p></li></ul><p>示例：</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">sub</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">10086</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">username</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">zhangsan</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">role</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">admin</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">iat</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 1719302400</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">exp</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 1719306000</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h3 id="_3-signature-签名" tabindex="-1">3. Signature（签名） <a class="header-anchor" href="#_3-signature-签名" aria-label="Permalink to “3. Signature（签名）”">​</a></h3><p>由「编码后的 Header + <code>.</code> + 编码后的 Payload」拼接后，通过 Header 声明的算法 + 服务端密钥计算得出，是第三段。 核心作用：<strong>防篡改</strong>—— 只要 Header 或 Payload 被改动，重新计算的签名就会与原签名不一致，服务端可直接拒绝。</p><p>以 HS256 为例，计算逻辑：</p><div class="language-Plain"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>HMACSHA256(</span></span>
<span class="line"><span>  base64UrlEncode(header) + &quot;.&quot; + base64UrlEncode(payload),</span></span>
<span class="line"><span>  服务端保密密钥</span></span>
<span class="line"><span>)</span></span></code></pre></div><h2 id="完整工作流程" tabindex="-1">完整工作流程 <a class="header-anchor" href="#完整工作流程" aria-label="Permalink to “完整工作流程”">​</a></h2><ol><li><p><strong>签发</strong>：用户登录成功后，服务端组装用户信息与标准字段生成 Payload，搭配 Header，用密钥计算签名，拼接成完整 JWT 返回前端。</p></li><li><p><strong>携带</strong>：前端后续请求在 <code>Authorization</code> 请求头中携带，标准格式为 <code>Bearer &lt;token&gt;</code>。</p></li><li><p><strong>校验</strong>：服务端收到请求后依次执行：</p><ul><li><p>拆分三段，对 Header+Payload 用相同算法 + 密钥重新计算签名；</p></li><li><p>对比计算签名与 Token 携带的签名是否一致；</p></li><li><p>校验 <code>exp</code> 过期时间、<code>iss</code> 签发者、<code>aud</code> 受众等声明；</p></li><li><p>全部校验通过则信任 Payload 中的用户信息，执行业务逻辑。</p></li></ul></li></ol><h2 id="两种主流签名算法对比" tabindex="-1">两种主流签名算法对比 <a class="header-anchor" href="#两种主流签名算法对比" aria-label="Permalink to “两种主流签名算法对比”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>HS256（对称加密）</th><th>RS256（非对称加密）</th></tr></thead><tbody><tr><td>密钥机制</td><td>单密钥，签发和验签使用同一个</td><td>公私钥对，私钥签发、公钥验签</td></tr><tr><td>安全风险</td><td>密钥泄露即可伪造所有 Token</td><td>公钥可公开，仅私钥泄露会有伪造风险</td></tr><tr><td>计算性能</td><td>运算快，性能高</td><td>运算慢，性能稍低</td></tr><tr><td>适用场景</td><td>单体应用、前后端同团队内部</td><td>微服务多节点、第三方授权、跨系统鉴权</td></tr></tbody></table><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to “核心特性”">​</a></h2><ol><li><p><strong>自包含</strong>：令牌本身携带身份、权限等信息，服务端无需查库即可完成鉴权，降低数据库压力。</p></li><li><p><strong>无状态</strong>：服务端不需要存储令牌，天然支持分布式多实例部署，无需做 Session 共享同步。</p></li><li><p><strong>跨语言通用</strong>：基于 JSON 标准，Java/Go/Node.js/Python 等所有主流语言都能生成与解析。</p></li><li><p><strong>防篡改</strong>：基于数字签名机制，中间人修改内容会立刻被校验识别。</p></li></ol><h2 id="核心局限与常见误区" tabindex="-1">核心局限与常见误区 <a class="header-anchor" href="#核心局限与常见误区" aria-label="Permalink to “核心局限与常见误区”">​</a></h2><h3 id="_1-最大局限-签发后默认无法主动吊销" tabindex="-1">1. 最大局限：签发后默认无法主动吊销 <a class="header-anchor" href="#_1-最大局限-签发后默认无法主动吊销" aria-label="Permalink to “1. 最大局限：签发后默认无法主动吊销”">​</a></h3><p>无状态是 JWT 的优势，也是最大代价：只要在有效期内，服务端默认无法让 Token 立刻失效。</p><p>行业主流解决方案：</p><ul><li><p><strong>短有效期 + 刷新令牌</strong>：Access Token 设 5~30 分钟，配合 Refresh Token 实现无感刷新，缩短泄露后的风险窗口；</p></li><li><p><strong>黑名单机制</strong>：用户登出、改密码、踢下线时，将 Token 的 <code>jti</code> 存入 Redis，过期时间与 Token 一致，鉴权时先查黑名单；</p></li><li><p><strong>关键操作二次校验</strong>：支付、改密等高敏感操作，额外校验密码或短信验证码，不单独依赖 JWT。</p></li></ul><h3 id="_2-常见认知误区" tabindex="-1">2. 常见认知误区 <a class="header-anchor" href="#_2-常见认知误区" aria-label="Permalink to “2. 常见认知误区”">​</a></h3><ul><li><p>❌ 误区 1：JWT 是加密的，内容别人看不到 ✅ 事实：默认 JWT 只是 Base64 编码，明文可逆。需要内容加密请使用 JWE（JSON Web Encryption），绝大多数业务场景无需使用。</p></li><li><p>❌ 误区 2：JWT 一定比 Session 更安全 ✅ 事实：两者风险点不同。JWT 怕传输泄露、怕密钥泄露；Session 怕 CSRF、怕会话劫持。没有绝对更安全，只有场景适配。</p></li><li><p>❌ 误区 3：JWT 必须存 localStorage ✅ 事实：存储方式是前端选择，与 JWT 本身无关。localStorage 易受 XSS 攻击窃取；HttpOnly + Secure Cookie 可防 XSS 读取，但存在 CSRF 风险。</p></li><li><p>❌ 误区 4：Payload 可以随便放数据 ✅ 事实：JWT 通常放在请求头中，体积过大会增加请求开销，且部分网关、服务器有 Header 大小限制。只存放必要的身份与权限字段。</p></li></ul><h2 id="适用与不适用场景" tabindex="-1">适用与不适用场景 <a class="header-anchor" href="#适用与不适用场景" aria-label="Permalink to “适用与不适用场景”">​</a></h2><h3 id="推荐使用" tabindex="-1">推荐使用 <a class="header-anchor" href="#推荐使用" aria-label="Permalink to “推荐使用”">​</a></h3><ul><li><p>前后端分离项目、移动端 / 小程序鉴权</p></li><li><p>微服务架构、跨服务身份传递</p></li><li><p>单点登录（SSO）</p></li><li><p>OAuth2.0 / OpenID Connect 体系（ID Token 本质就是 JWT）</p></li></ul><h3 id="不推荐使用" tabindex="-1">不推荐使用 <a class="header-anchor" href="#不推荐使用" aria-label="Permalink to “不推荐使用”">​</a></h3><ul><li><p>需要频繁吊销令牌、强制踢下线的高安全场景（如金融、政务）</p></li><li><p>需要存储大量用户会话数据的场景</p></li><li><p>纯服务端渲染（SSR）项目，Session Cookie 通常更简单高效</p></li></ul><h2 id="工程最佳实践" tabindex="-1">工程最佳实践 <a class="header-anchor" href="#工程最佳实践" aria-label="Permalink to “工程最佳实践”">​</a></h2><ol><li><p><strong>严格控制过期时间</strong>：Access Token 不超过 30 分钟，敏感业务不超过 5 分钟；Refresh Token 可设 7~30 天。</p></li><li><p><strong>高强度密钥管理</strong>：HS256 密钥长度建议 ≥ 32 位随机字符串，禁止硬编码在代码中，通过环境变量或配置中心注入。</p></li><li><p><strong>开启多维度校验</strong>：除签名和过期时间外，建议校验 <code>iss</code> 签发者、<code>aud</code> 受众，避免跨项目 Token 被复用。</p></li><li><p><strong>禁止存放敏感信息</strong>：密码、手机号、身份证号等绝不能放入 Payload。</p></li><li><p><strong>强制 HTTPS 传输</strong>：防止传输过程中 Token 被中间人窃取。</p></li><li><p><strong>必要时搭配黑名单</strong>：存在登出、多设备管理需求的系统，配合 Redis 实现短周期黑名单。</p></li></ol><h2 id="核心特点" tabindex="-1">核心特点 <a class="header-anchor" href="#核心特点" aria-label="Permalink to “核心特点”">​</a></h2><ul><li>自包含：Payload 里自带用户信息、过期时间、权限，服务端不用查 Redis / 数据库就能解析；</li><li>防篡改：服务端用密钥校验签名，payload 一旦改动直接失效；</li><li>无状态：服务端不用存储令牌（传统 session 存在服务端）；</li></ul><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to “历史”">​</a></h2><p>因为 HTTP 是无状态的，每次请求都需要包含用户信息， 用户信息存储在 session 中， 也就是存在服务端，会给服务端带来压力， 同时 session 有状态， 不能跨域， 不能被客户端修改。</p><h2 id="有哪些缺点" tabindex="-1">有哪些缺点？ <a class="header-anchor" href="#有哪些缺点" aria-label="Permalink to “有哪些缺点？”">​</a></h2><ul><li>无状态：服务端不用存储令牌（传统 session 存在服务端）， 但是服务端需要存储 jwt 信息， 会增加服务端压力，；</li><li>不能跨域：客户端不能将 jwt 放在请求头中， 跨域请求时， 服务器端不能检查 jwt 是否有效；</li><li>不能被客户端修改：客户端不能将 jwt 放在请求头中， 跨域请求时， 服务器端不能检查 jwt 是否有效；</li></ul>`,46)])])}const F=s(n,[["render",t]]);export{y as __pageData,F as default};
